/* Four editable composition plans, expressed as proportional areas. */
'use strict';
globalThis.SplitBlueprint=(()=>{
 const roles=['logo','text','image','offer','cta'],labels={logo:'Logo',text:'Texto',image:'Imagem',offer:'Oferta',cta:'Botão'};
 const families={horizontal:{label:'Horizontal',ratio:1.8,description:'Quadradas e horizontais · largura de 1× a 3× a altura'},wide:{label:'Superhorizontal',ratio:5,description:'Largura de pelo menos 3× a altura'},vertical:{label:'Vertical',ratio:.7,description:'Altura de até 2× a largura'},tall:{label:'Supervertical',ratio:.32,description:'Altura maior que 2× a largura'}};
 const rect=(x,y,w,h)=>({x,y,w,h});
 const defaults={horizontal:{logo:rect(.05,.05,.22,.12),text:rect(.05,.22,.43,.3),image:rect(.54,.07,.41,.69),offer:rect(.05,.56,.43,.17),cta:rect(.12,.8,.35,.13)},wide:{logo:rect(.025,.18,.13,.64),text:rect(.18,.1,.26,.8),image:rect(.46,.08,.21,.84),offer:rect(.69,.17,.14,.66),cta:rect(.85,.21,.125,.58)},vertical:{logo:rect(.07,.04,.35,.1),text:rect(.07,.18,.86,.2),image:rect(.07,.42,.86,.3),offer:rect(.12,.76,.76,.1),cta:rect(.2,.9,.6,.07)},tall:{logo:rect(.12,.03,.76,.09),text:rect(.08,.16,.84,.22),image:rect(.08,.42,.84,.27),offer:rect(.1,.74,.8,.1),cta:rect(.12,.9,.76,.065)}};
 let state={enabled:true,templates:clone(defaults)},draft=null,family='horizontal',role='image',gesture=null,generateAfter=false;
 const classify=(w,h)=>w/h>=3?'wide':w/h>=1?'horizontal':w/h>=.5?'vertical':'tall';
 function normal(box){const finite=(v,f)=>Number.isFinite(Number(v))?Number(v):f,w=clamp(finite(box.w,.05),.04,1),h=clamp(finite(box.h,.05),.04,1);return{x:clamp(Number(box.x)||0,0,1-w),y:clamp(Number(box.y)||0,0,1-h),w,h};}
 function restore(value){state=value?clone(value):{enabled:false,templates:clone(defaults)};draft=null;syncLabel();}
 function syncLabel(){$('planLayout').textContent=state.enabled?'Planejar layout':'Layout automático';}
 function frame(c,key){const pad=26,ratio=families[key].ratio,w=Math.min(c.width-pad*2,(c.height-pad*2)*ratio),h=w/ratio;return{x:(c.width-w)/2,y:(c.height-h)/2,w,h};}
 function drawPlan(c,key,templates,mini=false){const ctx=c.getContext('2d'),r=frame(c,key),dark=document.documentElement.dataset.theme==='dark';ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle=dark?'#171717':'#ffffff';ctx.fillRect(r.x,r.y,r.w,r.h);ctx.strokeStyle=dark?'#555555':'#cfd2d4';ctx.lineWidth=1;ctx.strokeRect(r.x,r.y,r.w,r.h);for(const item of roles){const b=templates[key][item],x=r.x+b.x*r.w,y=r.y+b.y*r.h,w=b.w*r.w,h=b.h*r.h,active=!mini&&item===role;ctx.fillStyle=active?'#e8502e25':dark?'#383838':'#eef0f2';ctx.strokeStyle=active?'#e8502e':dark?'#7b7b7b':'#92999d';ctx.lineWidth=active?2:1;ctx.fillRect(x,y,w,h);ctx.strokeRect(x,y,w,h);if(!mini){ctx.save();ctx.beginPath();ctx.rect(x+2,y+2,Math.max(1,w-4),Math.max(1,h-4));ctx.clip();ctx.font='500 15px Figtree, sans-serif';ctx.fillStyle=active?'#e8502e':dark?'#eeeeee':'#40474b';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(labels[item],x+w/2,y+h/2);ctx.restore();if(active)for(const [cx,cy]of[[x,y],[x+w,y],[x,y+h],[x+w,y+h]]){ctx.fillStyle=dark?'#171717':'#ffffff';ctx.fillRect(cx-3,cy-3,6,6);ctx.strokeStyle='#e8502e';ctx.strokeRect(cx-3,cy-3,6,6);}}}return r;}
 function draw(){if(!draft)return;drawPlan($('blueprintCanvas'),family,draft.templates);for(const button of $('blueprintFamilies').children){button.setAttribute('aria-pressed',String(button.dataset.family===family));drawPlan(button.querySelector('canvas'),button.dataset.family,draft.templates,true);}for(const button of $('blueprintRoles').children)button.setAttribute('aria-pressed',String(button.dataset.role===role));const box=draft.templates[family][role];for(const key of ['x','y','w','h'])$('blueprint-'+key).value=String(Math.round(box[key]*1000)/10);$('blueprintSelection').textContent=`Área de ${labels[role]}`;$('blueprintFamilyHint').textContent=families[family].description;$('blueprintEnabled').checked=draft.enabled;const overlaps=roles.some((a,i)=>roles.slice(i+1).some(b=>SplitLayout.overlap(draft.templates[family][a],draft.templates[family][b])));$('blueprintWarning').hidden=!overlaps;$('blueprintWarning').textContent=overlaps?'Há áreas sobrepostas. Os elementos podem precisar de ajustes depois de gerar.':'';}
 function open(runGeneration=false){generateAfter=runGeneration;SplitEditor.finishInteraction();draft=clone(state);family=classify(current()?.w||1200,current()?.h||628);role='image';$('saveBlueprint').textContent=runGeneration?'Salvar e gerar':'Salvar plano';draw();$('blueprintDialog').showModal();}
 function choose(key){if(families[key]){family=key;gesture=null;draw();}}
 function update(item,box){if(!draft||!roles.includes(item))return;draft.templates[family][item]=normal(box);draw();}
 function position(ev){const c=$('blueprintCanvas'),r=c.getBoundingClientRect();return{x:(ev.clientX-r.left)*c.width/r.width,y:(ev.clientY-r.top)*c.height/r.height};}
 function start(ev){if(ev.button!==0||!draft)return;const c=$('blueprintCanvas'),p=position(ev),r=frame(c,family),selected=draft.templates[family][role],px={x:r.x+selected.x*r.w,y:r.y+selected.y*r.h,w:selected.w*r.w,h:selected.h*r.h};let corner=null;const tolerance=10*c.width/c.getBoundingClientRect().width;for(const [name,x,y]of[['nw',px.x,px.y],['ne',px.x+px.w,px.y],['sw',px.x,px.y+px.h],['se',px.x+px.w,px.y+px.h]])if(Math.hypot(p.x-x,p.y-y)<=tolerance)corner=name;if(!corner){const hit=[...roles].reverse().find(item=>{const b=draft.templates[family][item];return p.x>=r.x+b.x*r.w&&p.x<=r.x+(b.x+b.w)*r.w&&p.y>=r.y+b.y*r.h&&p.y<=r.y+(b.y+b.h)*r.h;});if(!hit)return;role=hit;}ev.preventDefault();c.setPointerCapture(ev.pointerId);gesture={pointerId:ev.pointerId,start:p,box:clone(draft.templates[family][role]),corner,frame:r};draw();}
 function move(ev){const g=gesture;if(!g||g.pointerId!==ev.pointerId)return;ev.preventDefault();const p=position(ev),dx=(p.x-g.start.x)/g.frame.w,dy=(p.y-g.start.y)/g.frame.h,b=g.box;let next;if(!g.corner)next={...b,x:b.x+dx,y:b.y+dy};else{const east=g.corner.includes('e'),south=g.corner.includes('s'),left=east?b.x:clamp(b.x+dx,0,b.x+b.w-.04),top=south?b.y:clamp(b.y+dy,0,b.y+b.h-.04),right=east?clamp(b.x+b.w+dx,b.x+.04,1):b.x+b.w,bottom=south?clamp(b.y+b.h+dy,b.y+.04,1):b.y+b.h;next={x:left,y:top,w:right-left,h:bottom-top};}for(const key of ['x','y','w','h'])next[key]=Math.round(next[key]*1000)/1000;update(role,next);}
 function finish(ev){if(gesture&&(!ev||gesture.pointerId===ev.pointerId)){gesture=null;}}
 function apply(){if(!draft)return false;finish();checkpoint();state=clone(draft);draft=null;syncLabel();$('blueprintDialog').close();globalThis.SplitProjects?.changed();if(generateAfter){generateAfter=false;generate();}else toast('Plano salvo. Gere as composições para aplicá-lo.');return true;}
 for(const key of Object.keys(families)){const button=document.createElement('button');button.type='button';button.className='blueprint-family';button.dataset.family=key;const c=document.createElement('canvas');c.width=220;c.height=125;c.setAttribute('aria-hidden','true');const name=document.createElement('span');name.textContent=families[key].label;button.append(c,name);button.onclick=()=>choose(key);$('blueprintFamilies').append(button);}
 for(const item of roles){const button=document.createElement('button');button.type='button';button.dataset.role=item;button.textContent=labels[item];button.onclick=()=>{role=item;draw();};$('blueprintRoles').append(button);}
 for(const key of ['x','y','w','h'])$('blueprint-'+key).onchange=ev=>{const value=Number(ev.target.value);if(!Number.isFinite(value)){draw();return;}update(role,{...draft.templates[family][role],[key]:value/100});};
 const c=$('blueprintCanvas');c.onpointerdown=start;c.onpointermove=move;for(const event of ['pointerup','pointercancel','lostpointercapture'])c['on'+event]=finish;
 $('blueprintEnabled').onchange=ev=>{draft.enabled=ev.target.checked;};$('blueprintReset').onclick=()=>{draft.templates[family]=clone(defaults[family]);draw();};$('planLayout').onclick=()=>open();$('generate').onclick=()=>{if(!chosenFormats().length){toast('Escolha ao menos um formato de saída.');return;}if(!sources.length&&!backgroundSource&&!solidBackgroundChosen){toast('Escolha uma cor de fundo ou adicione uma imagem ou elemento.');return;}open(true);};$('saveBlueprint').onclick=apply;$('closeBlueprint').onclick=()=>$('blueprintDialog').close();$('blueprintDialog').addEventListener('close',()=>{draft=null;gesture=null;});syncLabel();
 return{enabled:()=>state.enabled,classify,slot:(f,item)=>state.templates[classify(f.w,f.h)][item],label:f=>families[classify(f.w,f.h)].label,state:()=>clone(state),restore,isCustom:()=>state.enabled!==true||JSON.stringify(state.templates)!==JSON.stringify(defaults),open,apply,choose,update,draft:()=>draft?clone(draft):null,start,move,finish,frame};
})();
